const raw = $input.item.json;

// Body arrives in 3 possible formats depending on Content-Type:
//   application/json  → raw.body is already a parsed object
//   text/plain        → raw.body is a JSON string, must JSON.parse
//   fallback          → data is flat on raw itself
let data;
if (raw.body && typeof raw.body === 'object') {
  data = raw.body;                              // JSON POST
} else if (raw.body && typeof raw.body === 'string') {
  try { data = JSON.parse(raw.body); }          // text/plain POST with JSON string
  catch(e) { data = {}; }
} else if (raw.rawBody && typeof raw.rawBody === 'string') {
  try { data = JSON.parse(raw.rawBody); }       // rawBody fallback
  catch(e) { data = raw; }
} else {
  data = raw;                                   // flat webhook or manual test
