const headContent = headMatch ? headMatch[1] : '';
const styleTags = [];
let sm; const sRx = /<style[\s\S]*?<\/style>/gi; while((sm=sRx.exec(headContent))!==null) styleTags.push(sm[0]);
let lm; const lRx = /<link[^>]+(?:stylesheet|font)[^>]*\/?>/gi; while((lm=lRx.exec(headContent))!==null) styleTags.push(lm[0]);
